import assert from'node:assert/strict';import http from'node:http';import{readFile,writeFile,mkdir}from'node:fs/promises';import{chromium}from'playwright';
const runtime=await readFile('scripts/component-product-ordering.js','utf8'),count=10000,size=20,items={},cards=[];
for(let i=0;i<count;i++){const key='products/p'+i;items[key]={price:String(count-i),min:String(count-i),max:String(count-i),id:i+1};cards.push({key,html:`<li class="product" data-migration-record="${key}"><a href="/product/p${i}/"><div class="image"><img alt="Product ${i}" width="300" height="300" src="data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///ywAAAAAAQABAAACAUwAOw=="></div><h2>Product ${i}</h2><span class="price"><bdi>$${count-i}</bdi></span></a><button disabled>Buy</button></li>`});}
const manifest=JSON.stringify({schema:'website-cloner-catalog/v1',items,cards}),cfg={manifest:'/assets/catalog.json',root:'/shop/',size,page:1,supported:['menu_order','price','price-desc']};let fetches=0,browser;
const server=http.createServer((req,res)=>{if(req.url==='/assets/catalog.json'){fetches++;res.setHeader('Content-Type','application/json');res.end(manifest);return;}res.setHeader('Content-Type','text/html');res.end(`<html><body><form class="woocommerce-ordering" data-cloner-product-ordering='${JSON.stringify(cfg)}'><select class="orderby" disabled><option value="menu_order">Default</option><option value="price">Price</option><option value="price-desc">High</option></select></form><ul class="products columns-4">${cards.slice(0,size).map(c=>c.html).join('')}</ul><script>${runtime}</script></body></html>`);});await new Promise(r=>server.listen(0,'127.0.0.1',r));
try{browser=await chromium.launch({channel:'chrome'});const page=await browser.newPage(),cdp=await page.context().newCDPSession(page);await page.goto('http://127.0.0.1:'+server.address().port+'/shop/');await cdp.send('HeapProfiler.collectGarbage');const before=await cdp.send('Runtime.getHeapUsage');const start=performance.now();await page.locator('select').selectOption('price');await page.waitForFunction(()=>document.querySelector('[role=status]').textContent.includes('page 1 of 500'));const firstMs=performance.now()-start;assert.equal(await page.locator('ul.products > li').count(),20);assert.equal(await page.locator('ul.products > li h2').first().textContent(),'Product 9999');await cdp.send('HeapProfiler.collectGarbage');const after=await cdp.send('Runtime.getHeapUsage'),dom=await cdp.send('Memory.getDOMCounters');const repeatStart=performance.now();await page.locator('select').selectOption('price-desc');await page.waitForFunction(()=>document.querySelector('ul.products > li h2').textContent==='Product 0');const cachedMs=performance.now()-repeatStart;assert.equal(fetches,1);
const report={scope:'Synthetic realistic-card browser benchmark on this machine; not a full migration benchmark',products:count,pageSize:size,manifestBytes:Buffer.byteLength(manifest),firstMs,cachedMs,heapBefore:before.usedSize,heapAfter:after.usedSize,heapDelta:after.usedSize-before.usedSize,domNodes:dom.nodes,documents:dom.documents,requests:fetches};await mkdir('artifacts/platform/catalog-scale',{recursive:true});await writeFile('artifacts/platform/catalog-scale/'+(process.env.CATALOG_SCALE_LABEL||'current')+'.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report));}finally{await browser?.close();await new Promise(r=>server.close(r));}
